//! Safe classification of a complete initial HTTP rejection, before any Task.
use super::*;

pub(super) fn initial_rejection(error: &a2a::A2AError) -> Option<Value> {
    // This marker is generated by our bounded HTTP decoder, never copied from
    // the peer's diagnostic message. 408/409/429 and all 5xx remain uncertain.
    let http = error.message.strip_prefix("A2A HTTP ").and_then(|value|value.parse::<u16>().ok());
    let grpc = error.message.strip_prefix("A2A gRPC ").and_then(|value|value.parse::<i32>().ok());
    if !http.is_some_and(|status|matches!(status,400|401|403|404|405|406|415|422))
        && !grpc.is_some_and(|code|matches!(code,3|5|7|12|16)) {return None;}
    let reason = (error.code != a2a::error_code::INTERNAL_ERROR).then(||a2a::error_reason(error.code));
    let code = reason.map(str::to_owned).unwrap_or_else(||match (http,grpc) {
        (Some(status),_)=>format!("HTTP_{status}"),(_,Some(code))=>format!("GRPC_{code}"),_=>unreachable!(),
    });
    Some(json!({"state":"error","errorKind":"a2a_protocol","errorCode":code,
        "errorMessage":diagnostic(error).to_string()}))
}

fn diagnostic(error:&a2a::A2AError)->Value {
    let status=error.message.strip_prefix("A2A HTTP ").and_then(|status|status.parse::<u16>().ok());
    let grpc=error.message.strip_prefix("A2A gRPC ").and_then(|code|code.parse::<i32>().ok());
    let reason=(error.code != a2a::error_code::INTERNAL_ERROR).then(||a2a::error_reason(error.code));
    let details: Vec<Value> = error.details.iter().flatten()
        .filter(|detail|detail.type_url == "type.googleapis.com/google.rpc.ErrorInfo")
        .filter_map(|detail|detail.value.get("reason").and_then(Value::as_str))
        .filter_map(a2a::reason_to_error_code)
        .map(|code|json!({"type":"type.googleapis.com/google.rpc.ErrorInfo","reason":a2a::error_reason(code)}))
        .take(16).collect();
    // Arbitrary ErrorInfo metadata, URLs, messages and domain strings can carry
    // secrets. Keep only recognized typed reasons in the public diagnostic.
    json!({"httpStatus":status,"grpcCode":grpc,"reason":reason,"details":details})
}

pub(super) fn protocol_failure(error:&a2a::A2AError,operation:&str)->ServiceError {
    // Query/cancel errors are request failures, not proof of a Task terminal.
    invalid(&format!("{operation}: {}",diagnostic(error)))
}

impl A2aHttpTransport {
    pub(super) async fn rejected(&self, record:&mut A2aRunRecord, payload:Value) -> ServiceResult<BotDeliveryResult> {
        self.save(record,A2aRunState::Failed).await?;
        self.emit_payload(record,ChatEventState::Error,payload).await?;
        self.runtime()?.contexts.mark_provider_transport_terminal(&record.run_id).await;
        Ok(BotDeliveryResult {target_bot_id:record.scope.bot_id.clone(),delivered:false,
            error:Some(invalid("remote request rejected before Task creation"))})
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn complete_grpc_rejections_are_distinct_from_uncertain_transport_outcomes() {
        for code in [3,5,7,12,16] {
            let error=a2a::A2AError::internal(format!("A2A gRPC {code}"));
            assert!(initial_rejection(&error).is_some());
        }
        for code in [1,2,4,8,9,10,13,14,15] {
            let error=a2a::A2AError::internal(format!("A2A gRPC {code}"));
            assert!(initial_rejection(&error).is_none());
        }
    }
}
